usage:
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Videos.Characters.New(
		context.TODO(),
		openai.VideoCharacterNewParams{
			Video: io.Reader(bytes.NewBuffer([]byte("Example data"))),
			Name: "string",
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
